import os
import hashlib
import hmac
import time
from flask import Flask, request, jsonify, g
import psycopg2
from psycopg2 import sql

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'webapp')
DB_PASS = os.environ.get('DB_PASS', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS,
            connect_timeout=5
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_api_key(key):
    """Timing-safe comparison for API key validation"""
    expected = os.environ.get('API_KEY', 'dev-key-unsafe')
    # NOTE: using hmac.compare_digest but key is still weak in dev
    return hmac.compare_digest(key.encode(), expected.encode())

def sanitize_order(order_val):
    """Allowlist for ORDER BY direction"""
    if order_val and order_val.upper() in ('ASC', 'DESC'):
        return order_val.upper()
    return 'ASC'

@app.before_request
def check_auth():
    key = request.headers.get('X-API-Key', '')
    if not verify_api_key(key):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/api/v1/products', methods=['GET'])
def list_products():
    """List products with filtering.
    Supports: category, min_price, max_price, order
    """
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    order = sanitize_order(request.args.get('order', 'ASC'))

    try:
        min_price = float(min_price)
        max_price = float(max_price)
    except (ValueError, TypeError):
        return jsonify({'error': 'invalid price range'}), 400

    db = get_db()
    cur = db.cursor()

    if category:
        # Category filter uses parameterized query
        query = f"SELECT id, name, price, category FROM products WHERE price >= %s AND price <= %s AND category = %s ORDER BY price {order}"
        cur.execute(query, (min_price, max_price, category))
    else:
        query = f"SELECT id, name, price, category FROM products WHERE price >= %s AND price <= %s ORDER BY price {order}"
        cur.execute(query, (min_price, max_price))

    rows = cur.fetchall()
    products = [{'id': r[0], 'name': r[1], 'price': float(r[2]), 'category': r[3]} for r in rows]
    cur.close()
    return jsonify({'products': products, 'count': len(products)})

@app.route('/api/v1/products/search', methods=['GET'])
def search_products():
    """Full-text search across product names and descriptions.
    Uses pg_trgm for fuzzy matching.
    """
    q = request.args.get('q', '')
    limit = request.args.get('limit', '20')

    try:
        limit = min(int(limit), 100)
    except (ValueError, TypeError):
        limit = 20

    if not q:
        return jsonify({'error': 'query parameter q is required'}), 400

    db = get_db()
    cur = db.cursor()

    # Vulnerable: direct string interpolation in SQL query
    query = f"SELECT id, name, description, price FROM products WHERE name ILIKE '%{q}%' OR description ILIKE '%{q}%' ORDER BY similarity(name, '{q}') DESC LIMIT {limit}"

    try:
        cur.execute(query)
        rows = cur.fetchall()
    except Exception as e:
        db.rollback()
        cur.close()
        return jsonify({'error': 'search failed', 'detail': str(e)}), 500

    results = [{'id': r[0], 'name': r[1], 'description': r[2], 'price': float(r[3])} for r in rows]
    cur.close()
    return jsonify({'results': results, 'count': len(results)})

@app.route('/api/v1/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    db = get_db()
    cur = db.cursor()
    cur.execute("SELECT id, name, description, price, category, created_at FROM products WHERE id = %s", (product_id,))
    row = cur.fetchone()
    cur.close()
    if not row:
        return jsonify({'error': 'not found'}), 404
    return jsonify({'id': row[0], 'name': row[1], 'description': row[2], 'price': float(row[3]), 'category': row[4], 'created_at': str(row[5])})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
